/**
 * Regenerate the JS string module from the two HTML templates.
 *
 * The Netlify function (Node) cannot use Vite's `?raw` imports, so this keeps a
 * single source of truth: edit the HTML files, run `npm run email:templates`,
 * and commit the generated file alongside them.
 */

import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));

const [notification, autoReply] = await Promise.all([
  readFile(join(here, 'inquiry-notification.html'), 'utf8'),
  readFile(join(here, 'inquiry-autoreply.html'), 'utf8'),
]);

// JSON.stringify gives a safe JS string literal: quotes, newlines and backticks
// are all escaped, and `${` stays inert inside a double-quoted string.
const output = `// Generated by email-templates/generate.mjs. Do not edit by hand.\n` +
  `export const notificationTemplate = ${JSON.stringify(notification)};\n\n` +
  `export const autoReplyTemplate = ${JSON.stringify(autoReply)};\n`;

await writeFile(join(here, 'templates.generated.mjs'), output);
console.log('Wrote email-templates/templates.generated.mjs');
